/**
 * Edit Staff Profile / Add Staff: form -> confirm -> success, live against
 * POST /admin/warehouse-staff (create) and PATCH /admin/warehouse-staff/{id}
 * (update). Both need `admin.staff.manage` (SA/TOHFA all, MAIN own, SUB none).
 *
 * The form holds exactly the record's fields: name, designation, phone,
 * joined-on date and (on edit) status. Create also needs a warehouse when the
 * admin is not confined to one (Main, Super Admin): picked from GET
 * /warehouses (warehouse.all.view); a confined admin's own warehouse is used.
 * The staff code (STF-nnnn) is generated by the server and shown on success.
 * The PATCH sends only changed fields (BR-83g). No write moves money, and the
 * spec declares no Idempotency-Key on these routes.
 */
// Design id: M14-S02E
import React, { useState } from 'react';
import { ScrollView, StyleSheet, Text, TextInput, View } from 'react-native';

import { adminErrorKey } from '../../../api/errors';
import type { StaffDto } from '../../../api/staff';
import { t } from '../../../i18n';
import { adminColors, adminRadius, adminSpacing, adminType } from '../../../theme';
import { AdminEmptyState, AdminErrorState, AdminLoadingState } from '../shared/AsyncStates';
import {
  BackArrowIcon,
  CheckIcon,
  ChipGroup,
  InfoNote,
  SuccessCircleIcon,
  WalletButton,
  WalletFooter,
  WalletScreen,
  walletLayout,
} from '../wallet-cashtopup/WalletParts';
import {
  buildCreateStaffBody,
  buildUpdateStaffBody,
  canManageStaff,
  emptyStaffForm,
  istToday,
  STAFF_CODES,
  staffFormOf,
  staffStatusLabel,
  type StaffForm,
} from './mappers';
import { SaveIcon } from './StaffParts';
import type { StaffMember, StaffStatus, WarehouseScreenBaseProps } from './types';
import { useCreateStaffMutation, useStaffWarehouses, useUpdateStaffMutation } from './useStaffData';

type EditStep = 'form' | 'confirm' | 'success';
const STATUS_OPTIONS: readonly StaffStatus[] = ['ACTIVE', 'INACTIVE'];

export interface EditStaffProfileScreenProps extends WarehouseScreenBaseProps {
  /** The member to edit; undefined opens the form in "Add Staff" mode. */
  staff?: StaffMember | undefined;
  /** "Back to Staff List" on the success step. */
  onSave: () => void;
}

export function EditStaffProfileScreen({ scope, can, onBack, staff, onSave }: EditStaffProfileScreenProps) {
  const creating = staff === undefined;
  const allowed = canManageStaff(can);
  const [now] = useState(() => new Date());
  const [step, setStep] = useState<EditStep>('form');
  const [form, setForm] = useState<StaffForm>(() => (staff === undefined ? emptyStaffForm(istToday(now)) : staffFormOf(staff)));
  const [pickedWarehouseId, setPickedWarehouseId] = useState<string | undefined>(undefined);
  const [formError, setFormError] = useState<string | null>(null);
  const [saved, setSaved] = useState<StaffDto | null>(null);

  const confined = scope.warehouseId !== undefined;
  const pickerAllowed = creating && !confined && can(STAFF_CODES.warehouseList);
  const warehouses = useStaffWarehouses(scope, pickerAllowed ? can : () => false);
  const create = useCreateStaffMutation();
  const update = useUpdateStaffMutation();
  const mutationError = creating ? create.error : update.error;
  const pending = create.isPending || update.isPending;

  const titleText = creating ? t('staff.form.addTitle') : t('staff.form.editTitle');

  if (!allowed) {
    return (
      <WalletScreen title={titleText} onBack={onBack}>
        <AdminEmptyState title={t('staff.denied.title')} subtitle={t('staff.denied.manage')} />
      </WalletScreen>
    );
  }

  const set = (patch: Partial<StaffForm>) => setForm((prev) => ({ ...prev, ...patch }));
  const warehouseId = confined ? scope.warehouseId : pickedWarehouseId;

  const review = () => {
    const result = creating ? buildCreateStaffBody(form, warehouseId) : buildUpdateStaffBody(staff, form);
    if (!result.ok) {
      setFormError(t(result.errorKey));
      return;
    }
    setFormError(null);
    setStep('confirm');
  };

  const submit = () => {
    if (creating) {
      const result = buildCreateStaffBody(form, warehouseId);
      if (!result.ok) return;
      create.mutate(result.body, {
        onSuccess: (dto) => {
          setSaved(dto);
          setStep('success');
        },
      });
      return;
    }
    const result = buildUpdateStaffBody(staff, form);
    if (!result.ok) return;
    update.mutate(
      { id: staff.id, body: result.body },
      {
        onSuccess: (dto) => {
          setSaved(dto);
          setStep('success');
        },
      },
    );
  };

  if (step === 'success') {
    return (
      <WalletScreen
        title={creating ? t('staff.form.addedTitle') : t('staff.form.updatedTitle')}
        onBack={onSave}
        footer={
          <WalletFooter>
            <WalletButton label={t('staff.form.backToList')} icon={<BackArrowIcon />} onPress={onSave} />
          </WalletFooter>
        }
      >
        <View style={styles.successWrap}>
          <SuccessCircleIcon />
          <Text style={styles.successTitle}>{creating ? t('staff.form.addedTitle') : t('staff.form.updatedTitle')}</Text>
          <Text style={styles.successSubtitle}>{t('staff.list.meta', { code: saved?.staffCode ?? '', designation: saved?.designation ?? '' })}</Text>
        </View>
      </WalletScreen>
    );
  }

  if (step === 'confirm') {
    return (
      <WalletScreen title={titleText} onBack={() => setStep('form')}>
        <ScrollView contentContainerStyle={walletLayout.scrollContent}>
          <View style={styles.confirmCard}>
            <Text style={styles.confirmTitle}>{creating ? t('staff.form.confirmAdd') : t('staff.form.confirmSave')}</Text>
            <Text style={styles.confirmMessage}>{form.fullName.trim()}</Text>
            {mutationError ? <Text style={styles.errorText}>{t(adminErrorKey(mutationError))}</Text> : null}
            <View style={styles.confirmButtons}>
              <WalletButton label={t('staff.common.save')} icon={<CheckIcon />} disabled={pending} onPress={submit} />
              <WalletButton label={t('staff.common.cancel')} variant="neutral" onPress={() => setStep('form')} />
            </View>
          </View>
        </ScrollView>
      </WalletScreen>
    );
  }

  const field = (
    label: string,
    value: string,
    onChange: (v: string) => void,
    placeholder: string,
    keyboardType: 'default' | 'phone-pad' = 'default',
  ) => (
    <View style={styles.inputGroup}>
      <Text style={styles.label}>{label}</Text>
      <TextInput
        style={styles.input}
        value={value}
        onChangeText={onChange}
        placeholder={placeholder}
        placeholderTextColor={adminColors.placeholder}
        keyboardType={keyboardType}
        accessibilityLabel={label}
      />
    </View>
  );

  return (
    <WalletScreen
      title={titleText}
      onBack={onBack}
      footer={
        <WalletFooter>
          <WalletButton label={t('staff.common.save')} icon={<SaveIcon />} onPress={review} />
          <WalletButton label={t('staff.common.cancel')} variant="neutral" onPress={onBack} />
        </WalletFooter>
      }
    >
      <ScrollView contentContainerStyle={walletLayout.scrollContent} keyboardShouldPersistTaps="handled">
        {field(t('staff.field.name'), form.fullName, (v) => set({ fullName: v }), t('staff.form.namePlaceholder'))}
        {field(t('staff.field.designation'), form.designation, (v) => set({ designation: v }), t('staff.form.designationPlaceholder'))}
        {field(t('staff.field.phone'), form.phone, (v) => set({ phone: v }), t('staff.form.phonePlaceholder'), 'phone-pad')}
        {field(t('staff.field.joinedOn'), form.joinedOn, (v) => set({ joinedOn: v.trim() }), t('staff.form.datePlaceholder'))}

        {creating && !confined ? (
          <View style={styles.inputGroup}>
            <Text style={styles.label}>{t('staff.field.warehouse')}</Text>
            {!pickerAllowed ? (
              <InfoNote tone="warning">{t('staff.form.noWarehouseList')}</InfoNote>
            ) : warehouses.isLoading ? (
              <AdminLoadingState />
            ) : warehouses.error ? (
              <AdminErrorState error={warehouses.error} onRetry={warehouses.refresh} />
            ) : (
              <ChipGroup
                options={warehouses.options.map((o) => o.warehouseId)}
                value={pickedWarehouseId ?? ''}
                onChange={setPickedWarehouseId}
                labelOf={warehouses.nameOf}
              />
            )}
          </View>
        ) : null}

        {!creating ? (
          <View style={styles.inputGroup}>
            <Text style={styles.label}>{t('staff.field.status')}</Text>
            <ChipGroup options={STATUS_OPTIONS} value={form.status} onChange={(status) => set({ status })} labelOf={staffStatusLabel} />
          </View>
        ) : null}

        {formError !== null ? <Text style={styles.errorText}>{formError}</Text> : null}
        <InfoNote>{t('staff.detail.noHrNote')}</InfoNote>
      </ScrollView>
    </WalletScreen>
  );
}

const INPUT_HEIGHT = 46;

const styles = StyleSheet.create({
  inputGroup: { marginBottom: adminSpacing.md },
  label: { ...adminType.rowTitle, color: adminColors.ink, marginBottom: adminSpacing.sm },
  input: {
    ...adminType.body,
    height: INPUT_HEIGHT,
    backgroundColor: adminColors.card,
    borderWidth: 1,
    borderColor: adminColors.border,
    borderRadius: adminRadius.md,
    paddingHorizontal: adminSpacing.md,
    color: adminColors.ink,
  },
  errorText: { ...adminType.rowMeta, color: adminColors.danger.text, marginBottom: adminSpacing.md },
  confirmCard: {
    backgroundColor: adminColors.card,
    borderRadius: adminRadius.xl,
    borderWidth: 1,
    borderColor: adminColors.border,
    padding: adminSpacing.lg,
    marginTop: adminSpacing.md,
  },
  confirmTitle: { ...adminType.title, color: adminColors.ink },
  confirmMessage: { ...adminType.body, color: adminColors.muted, marginTop: adminSpacing.sm, marginBottom: adminSpacing.sm },
  confirmButtons: { gap: adminSpacing.sm, marginTop: adminSpacing.lg },
  successWrap: { flex: 1, alignItems: 'center', justifyContent: 'center', padding: adminSpacing.xl, gap: adminSpacing.sm },
  successTitle: { ...adminType.title, color: adminColors.ink, textAlign: 'center' },
  successSubtitle: { ...adminType.body, color: adminColors.muted, textAlign: 'center' },
});
